Here is the problem description:
<problem_description>
Firecrackers scare Nian the monster, but they're wayyyyy too noisy! Maybe fireworks make a nice complement.Little Tommy is watching a firework show. As circular shapes spread across the sky, a splendid view unfolds on the night of Lunar New Year's eve.A wonder strikes Tommy. How many regions are formed by the circles on the sky? We consider the sky as a flat plane. A region is a connected part of the plane with positive area, whose bound consists of parts of bounds of the circles and is a curve or several curves without self-intersections, and that does not contain any curve other than its boundaries. Note that exactly one of the regions extends infinitely.
</problem_description>

Here is the Java 8 code you have to repair:
<original_code>
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().start();
    }

    void start() {
        try {
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));

            int caseId = 1;
            String line;
            while (!(line = br.readLine()).isEmpty()) {
                String[] parts = line.trim().split("\\s+");
                int n = Integer.parseInt(parts[0]);
                int D = Integer.parseInt(parts[1]);
                if (n == 0 && D == 0) break;

                bw.write("@" + caseId++ + "\n");

                final double R = 1;
                Point left = new Point(-D, 0);
                Point right = new Point(D, 0);

                for (int i = 0; i < n; i++) {
                    parts = br.readLine().trim().split("\\s+");
                    int sl = Integer.parseInt(parts[0]);
                    int sr = Integer.parseInt(parts[1]);
                    double vLeft = sl * Math.PI * R / 180.0;
                    double vRight = sr * Math.PI * R / 180.0;
                    int t = Integer.parseInt(parts[2]);

                    if (sl == sr) {
                        Point delta = right.minus(left).rotate(Math.PI / 2).normalize().scale((vLeft + vRight) * 0.5 * t);
                        left = left.add(delta);
                        right = right.add(delta);
                        continue;
                    }

                    double x = D * (vLeft + vRight) / (vLeft - vRight);
                    Point mid = left.add(right).scale(0.5);
                    Point pivot = mid.add(right.minus(mid).normalize().scale(x));

                    Point lDir = left.minus(pivot);
                    Point rDir = right.minus(pivot);
                    double wLeft = vLeft / lDir.length();
                    double wRight = vRight / rDir.length();

                    lDir = lDir.rotate(wLeft * t);
                    rDir = rDir.rotate(wRight * t);

                    left = lDir.add(pivot);
                    right = rDir.add(pivot);
                }

                Point center = left.add(right).scale(0.5);
                bw.write(String.format("%.10f%n", center.x));
                bw.write(String.format("%.10f%n", center.y));
                bw.flush();
            }
            bw.close();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    static class Point {
        double x, y;

        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

        Point add(Point p) { return new Point(x + p.x, y + p.y); }
        Point minus(Point p) { return new Point(x - p.x, y - p.y); }

        Point rotate(double angle) {
            double c = Math.cos(angle), s = Math.sin(angle);
            return new Point(x * c - y * s, x * s + y * c);
        }

        Point normalize() {
            double len = length();
            return scale(1.0 / len);
        }

        Point scale(double f) { return new Point(f * x, f * y); }

        double length() { return Math.sqrt(x * x + y * y); }
    }
}
